style.css:
/* AKSHII AI - MIDNIGHT CYBER */

/* MAIN BACKGROUND */
html,
body {
    background: #080611 !important;
    color: #f5f3ff !important;
}

/* CHAT AREA */
main {
    background:
        radial-gradient(circle at 20% 20%, rgba(168, 85, 247, 0.12), transparent 35%),
        radial-gradient(circle at 80% 80%, rgba(34, 211, 238, 0.08), transparent 35%),
        #080611 !important;
}

/* SIDEBAR */
aside {
    background: rgba(10, 7, 20, 0.96) !important;
    border-right: 1px solid rgba(168, 85, 247, 0.2) !important;
}

/* SIDEBAR HOVER */
aside button:hover,
aside a:hover {
    background: rgba(168, 85, 247, 0.12) !important;
}

/* USER MESSAGES */
[data-message-author-role="user"] {
    background: rgba(168, 85, 247, 0.12) !important;
    border: 1px solid rgba(168, 85, 247, 0.2) !important;
    border-radius: 18px !important;
}

/* AI MESSAGES */
[data-message-author-role="assistant"] {
    background: rgba(20, 14, 38, 0.25) !important;
    border-radius: 18px !important;
}

/* LINKS */
a {
    color: #c084fc !important;
}

a:hover {
    color: #22d3ee !important;
}

/* TEXT BOX */
textarea {
    background: rgba(15, 9, 27, 0.9) !important;
    color: white !important;
    border: 1px solid rgba(168, 85, 247, 0.3) !important;
    border-radius: 18px !important;
}

/* TEXT BOX FOCUS */
textarea:focus {
    border-color: rgba(168, 85, 247, 0.7) !important;
    box-shadow: 0 0 25px rgba(168, 85, 247, 0.15) !important;
}

/* CODE BLOCKS */
pre {
    background: #0b0715 !important;
    border: 1px solid rgba(168, 85, 247, 0.2) !important;
    border-radius: 14px !important;
}

/* INLINE CODE */
code {
    background: rgba(168, 85, 247, 0.1) !important;
}

/* BUTTON HOVER */
button:hover {
    background: rgba(168, 85, 247, 0.1) !important;
}

/* MENUS */
[role="menu"],
[role="dialog"] {
    background: rgba(12, 8, 23, 0.97) !important;
    border: 1px solid rgba(168, 85, 247, 0.2) !important;
    border-radius: 14px !important;
}

/* SCROLLBAR */
* {
    scrollbar-color: #8b5cf6 #080611;
}

*::-webkit-scrollbar {
    width: 7px;
}

*::-webkit-scrollbar-track {
    background: #080611;
}

*::-webkit-scrollbar-thumb {
    background: #8b5cf6;
    border-radius: 10px;
}

/* TEXT SELECTION */
::selection {
    background: rgba(168, 85, 247, 0.4) !important;
    color: white !important;
}
